        let target = this.data;
        while (parts.length > 1) {
            const part = parts.shift();
            if (!target[part] || typeof target[part] !== "object") target[part] = {};
            target = target[part];
        }
        target[parts[0]] = value;
        Storage.set("settings", this.data);
        this.apply();
